            aOrbiterI = ((aWandererA + RotL64(aPrevious, 47U)) + 0x1EFCF83EC9F17F36ULL) + aOASaltD[((aIndex + 402U)) & S_SALT1];
            aOrbiterB = ((aWandererE + RotL64(aIngress, 23U)) + RotL64(aCarry, 13U)) + 0x253649BC6D607A65ULL;
            aOrbiterH = ((aWandererB + RotL64(aCross, 53U)) + 0x8681ED30184AE9F4ULL) + aOASaltG[((aIndex + 317U)) & S_SALT1];
            aOrbiterD = ((aWandererI + RotL64(aScatter, 18U)) + RotL64(aCarry, 37U)) + 0xF576C0674C076733ULL;
