            aOrbiterB = ((aWandererA + RotL64(aIngress, 41U)) + 0xB8414A5AA0A6AC0BULL) + aOASaltA[((aIndex + 119U)) & S_SALT1];
            aOrbiterI = (aWandererD + RotL64(aScatter, 27U)) + 0x6618762A259A196AULL;
            aOrbiterK = (((aWandererF + RotL64(aCross, 48U)) + RotL64(aCarry, 35U)) + 0xDE36578E49EE550FULL) + aOASaltG[(((511U - aIndex) + 497U)) & S_SALT1];
            //
            aOrbiterE = (aOrbiterE + aOrbiterC) + 0x1389C7A329F61D86ULL;
