            aOrbiterC = ((aOrbiterC ^ aOrbiterI) ^ 0xE2B09E3EFC651355ULL) ^ aOUSaltF[((aIndex + 82U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xD4E2A864B92B463DULL), 3U);
            //
            aIngress = RotL64(aOrbiterE, 58U) ^ aOrbiterB;
            aIngress = aIngress + (aOrbiterK ^ RotL64(aOrbiterF, 27U));
            aIngress = aIngress + (aOrbiterC ^ RotL64(aOrbiterI, 19U));
            aIngress = aIngress + RotL64(aOrbiterA, 11U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererE = aWandererE ^ (((RotL64(aIngress, 4U) + RotL64(aOrbiterK, 57U)) + aOrbiterF) + aWUSaltD[(((511U - aIndex) + 486U)) & S_SALT1]);
