            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterI = ((aWandererF + RotL64(aPrevious, 11U)) + 0xC77473859D78FB2BULL) + aOASaltB[(((511U - aIndex) + 434U)) & S_SALT1];
            aOrbiterB = ((aWandererC + RotL64(aCross, 57U)) + RotL64(aCarry, 41U)) + 0x484AB182AF5CABE5ULL;
            aOrbiterC = ((aWandererB + RotL64(aScatter, 41U)) + RotL64(aCarry, 13U)) + 0x7BC89A97C4AAB24AULL;
            aOrbiterF = ((aWandererE + RotL64(aIngress, 30U)) + 0x485856E45D976B9DULL) + aOASaltE[(((511U - aIndex) + 279U)) & S_SALT1];
            aOrbiterG = (aWandererG + RotL64(aPrevious, 3U)) + 0x977573D07691D0EFULL;
            aOrbiterD = ((aWandererD + RotL64(aIngress, 51U)) + RotL64(aCarry, 57U)) + 0xDBA11ECDD3037D19ULL;
            aOrbiterA = ((aWandererH + RotL64(aCross, 19U)) + 0x878163C078B107F0ULL) + aOASaltC[((aIndex + 208U)) & S_SALT1];
