            aOrbiterC = (aOrbiterC + aOrbiterF) + 0xF7AD6351FC19A959ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterC) ^ 0x05B12C660D89848EULL) ^ aOUSaltG[((aIndex + 309U)) & S_SALT1];
