            //
            aOrbiterA = (aOrbiterA + aOrbiterC) + 0x5D5F452D448761B9ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterA) ^ 0x69A50C34310E7544ULL) ^ aOUSaltD[(((511U - aIndex) + 140U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x58FC3515992A4B77ULL), 3U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x09278328581F321CULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterB) ^ 0xE5503A318B0220C8ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xC6AD03784D8ED58BULL), 35U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0xD7AD2CD91249F38BULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterD) ^ 0x3DC2AA969BE32FE6ULL) ^ aOUSaltC[((aIndex + 314U)) & S_SALT1];
