            aWandererG = aWandererG ^ (((RotL64(aCross, 27U) + RotL64(aOrbiterD, 28U)) + aOrbiterA) + aWUSaltB[(((511U - aIndex) + 161U)) & S_SALT1]);
            aWandererE = aWandererE + ((((RotL64(aPrevious, 57U) + aOrbiterC) + RotL64(aOrbiterD, 5U)) + RotL64(aCarry, 27U)) + aWUSaltG[((aIndex + 483U)) & S_SALT1]);
