            aCross ^= (RotL64(aWoodLaneD[((S_BLOCK1 - aIndex + 19381U)) & S_BLOCK1], 27U) ^ RotL64(aShadowLaneB[((aIndex + 18658U)) & S_BLOCK1], 57U));
            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 56U) + RotL64(aCross, 39U)) ^ (RotL64(aCarry, 11U) ^ RotL64(aIngress, 23U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
