            aOrbiterA = ((aWandererE + RotL64(aPrevious, 3U)) + RotL64(aCarry, 3U)) + 0xD40FC795EE514F25ULL;
            aOrbiterJ = ((aWandererI + RotL64(aScatter, 23U)) + RotL64(aCarry, 19U)) + 0xF8BC9CA49672B213ULL;
            aOrbiterF = ((aWandererK + RotL64(aCross, 21U)) + 0x1ACAB36D2FBA3B18ULL) + aOASaltC[((aIndex + 152U)) & S_SALT1];
            aOrbiterC = ((aWandererH + RotL64(aIngress, 41U)) + 0x8DE843E393A670E0ULL) + aOASaltH[(((511U - aIndex) + 266U)) & S_SALT1];
            aOrbiterD = ((aWandererG + RotL64(aScatter, 38U)) + 0xAF48FDF51A3053DAULL) + aOASaltE[((aIndex + 59U)) & S_SALT1];
